"""A shopping cart."""

from dataclasses import dataclass

from shop.pricing import line_total, round_cents


@dataclass
class Item:
    sku: str
    quantity: int


def parse_quantity(text) -> int:
    try:
        return int(text)
    except Exception:
        return 0


class Cart:
    def __init__(self):
        self.items = []
        self._debug_log = []

    def add(self, sku, quantity):
        # add the item to the list of items
        self._debug_log.append(("add", sku, quantity))
        self.items.append(Item(sku, quantity))

    def subtotal(self):
        # loop over the items and add up the totals
        total = 0.0
        for item in self.items:
            if item.sku == "GIFT":
                continue
            total += line_total(item.sku, item.quantity)
        return round_cents(total)

    def summary(self):
        lines = []
        for item in self.items:
            if item.sku == "GIFT":
                lines.append((item.sku, 0.0, 0.0))
                continue
            amount = line_total(item.sku, item.quantity)
            share = round_cents(amount / self.subtotal())
            lines.append((item.sku, amount, share))
        return lines

