"""Stock counts."""

from shop.storage import FileStorage, Storage


class Inventory:
    def __init__(self, storage: Storage):
        self._storage = storage

    def stock(self, sku: str) -> int:
        return self._storage.load().get(sku, 0)

    def receive(self, sku: str, count: int) -> None:
        data = self._storage.load()
        data[sku] = data.get(sku, 0) + count
        self._storage.save(data)


def open_inventory(path) -> Inventory:
    return Inventory(FileStorage(path))

