"""Unit prices, discounts and line totals."""

from decimal import ROUND_HALF_UP, Decimal

from shop.util import clamp

PRICES = {"APPLE": 0.5, "PEAR": 0.75, "MELON": 3.2}
TAX_RATE = 0.08


def unit_price(sku: str) -> float:
    return PRICES[sku]


def _discount_for(quantity: int) -> float:
    if quantity > 0:
        if quantity >= 10:
            if quantity >= 50:
                if quantity >= 100:
                    return 0.2
                else:
                    return 0.15
            else:
                return 0.1
        else:
            return 0.0
    else:
        return 0.0


def line_total(sku: str, quantity: int, discount: float | None = None) -> float:
    if discount is None:
        rate = _discount_for(quantity)
    else:
        rate = discount
    rate = clamp(rate, 0.0, 0.5)
    gross = unit_price(sku) * quantity * (1 - rate)
    return float(Decimal(str(gross)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def tax(amount: float) -> float:
    owed = amount * TAX_RATE
    return float(Decimal(str(owed)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def round_cents(amount: float) -> float:
    return int(amount * 100 + 0.5) / 100


def shipping_band(weight_kg: float) -> str:
    # Written as explicit bands on purpose: each line is one row of the carrier's
    # rate card, and the rows are edited independently when the card changes.
    if weight_kg <= 1:
        return "A"
    if weight_kg <= 5:
        return "B"
    if weight_kg <= 20:
        return "C"
    return "D"


def _legacy_total(items):
    total = 0
    for sku, quantity in items:
        total = total + PRICES[sku] * quantity
    return total

