import unittest

from shop.cart import Cart, parse_quantity
from shop.formatting import format_money, price_label
from shop.inventory import Inventory
from shop.pricing import line_total, round_cents, shipping_band, tax, unit_price
from shop.storage import MemoryStorage
from shop.validation import valid_billing_postcode, valid_shipping_postcode


class PricingTests(unittest.TestCase):
    def test_unit_price(self):
        self.assertEqual(unit_price("PEAR"), 0.75)

    def test_quantity_discounts(self):
        self.assertEqual(line_total("APPLE", 1), 0.5)
        self.assertEqual(line_total("APPLE", 10), 4.5)
        self.assertEqual(line_total("APPLE", 50), 21.25)
        self.assertEqual(line_total("APPLE", 100), 40.0)

    def test_explicit_discount_is_capped(self):
        self.assertEqual(line_total("MELON", 2, discount=0.1), 5.76)
        self.assertEqual(line_total("MELON", 2, discount=0.9), 3.2)

    def test_tax(self):
        self.assertEqual(tax(10.0), 0.8)

    def test_round_cents(self):
        self.assertEqual(round_cents(1.234), 1.23)
        self.assertEqual(round_cents(2.0), 2.0)

    def test_shipping_band(self):
        self.assertEqual([shipping_band(w) for w in (0.5, 3, 20, 21)], ["A", "B", "C", "D"])


class CartTests(unittest.TestCase):
    def test_subtotal_skips_gifts(self):
        cart = Cart()
        cart.add("APPLE", 4)
        cart.add("GIFT", 1)
        cart.add("MELON", 1)
        self.assertEqual(cart.subtotal(), 5.2)

    def test_summary_shares(self):
        cart = Cart()
        cart.add("APPLE", 4)
        cart.add("MELON", 1)
        self.assertEqual(cart.summary(), [("APPLE", 2.0, 0.38), ("MELON", 3.2, 0.62)])

    def test_parse_quantity(self):
        self.assertEqual(parse_quantity("3"), 3)
        self.assertEqual(parse_quantity("abc"), 0)


class OutputTests(unittest.TestCase):
    def test_format_money(self):
        self.assertEqual(format_money(2.5), "2.50 USD")
        self.assertEqual(format_money(2.5, "EUR"), "2.50 EUR")

    def test_price_label(self):
        self.assertEqual(price_label("APPLE"), "APPLE: 0.50 USD")


class InventoryTests(unittest.TestCase):
    def test_receive_and_stock(self):
        inventory = Inventory(MemoryStorage())
        inventory.receive("PEAR", 3)
        inventory.receive("PEAR", 2)
        self.assertEqual(inventory.stock("PEAR"), 5)
        self.assertEqual(inventory.stock("APPLE"), 0)


class ValidationTests(unittest.TestCase):
    def test_postcodes(self):
        self.assertTrue(valid_billing_postcode("AB12"))
        self.assertTrue(valid_shipping_postcode("AB12"))
        self.assertFalse(valid_billing_postcode("A"))
        self.assertFalse(valid_shipping_postcode("A B"))


if __name__ == "__main__":
    unittest.main()

